import os
from PIL import Image

def batch_resize(input_dir, output_dir, target_size):
    os.makedirs(output_dir, exist_ok=True)
    valid_ext = ('.png', '.jpg', '.jpeg')
    processed, skipped = 0, []
    for fname in sorted(os.listdir(input_dir)):
        if not fname.lower().endswith(valid_ext):
            continue
        try:
            with Image.open(os.path.join(input_dir, fname)) as img:
                img.resize(target_size, Image.LANCZOS).save(os.path.join(output_dir, fname))
                processed += 1
        except Exception:
            skipped.append(fname)
    return {'processed_count': processed, 'skipped': skipped}

import os
from PIL import Image

def convert_format(input_dir, output_dir, target_format):
    target_format = target_format.upper()
    if target_format not in ('PNG', 'JPEG'):
        raise ValueError('target_format must be PNG or JPEG')
    os.makedirs(output_dir, exist_ok=True)
    ext = '.png' if target_format == 'PNG' else '.jpg'
    converted, errors = 0, []
    for fname in sorted(os.listdir(input_dir)):
        stem, fext = os.path.splitext(fname)
        if fext.lower() not in ('.png', '.jpg', '.jpeg'):
            continue
        try:
            with Image.open(os.path.join(input_dir, fname)) as img:
                if target_format == 'JPEG' and img.mode in ('RGBA', 'LA'):
                    background = Image.new('RGB', img.size, (255, 255, 255))
                    background.paste(img, mask=img.split()[-1])
                    img = background
                elif target_format == 'JPEG':
                    img = img.convert('RGB')
                img.save(os.path.join(output_dir, stem + ext), format=target_format)
                converted += 1
        except Exception:
            errors.append(fname)
    return {'converted': converted, 'errors': errors}

import os
from PIL import Image

def preprocess_images(input_dir, output_dir):
    os.makedirs(output_dir, exist_ok=True)
    valid_ext = ('.png', '.jpg', '.jpeg')
    stats = {}
    for fname in sorted(os.listdir(input_dir)):
        if not fname.lower().endswith(valid_ext):
            continue
        with Image.open(os.path.join(input_dir, fname)) as img:
            gray = img.convert('L')
            lo, hi = gray.getextrema()
            stem = os.path.splitext(fname)[0]
            if hi == lo:
                normalized = gray.point(lambda p: 255)
            else:
                scale_factor = 255.0 / (hi - lo)
                normalized = gray.point(lambda p: round((p - lo) * scale_factor))
            normalized.save(os.path.join(output_dir, stem + '.png'))
            stats[fname] = {'orig_min': lo, 'orig_max': hi}
    return stats

import os
from PIL import Image, ImageFilter

def apply_blur(input_dir, output_dir, radius):
    if radius < 0:
        raise ValueError('radius must be non-negative')
    os.makedirs(output_dir, exist_ok=True)
    valid_ext = ('.png', '.jpg', '.jpeg')
    count = 0
    for fname in sorted(os.listdir(input_dir)):
        if not fname.lower().endswith(valid_ext):
            continue
        with Image.open(os.path.join(input_dir, fname)) as img:
            if radius == 0:
                out = img.copy()
            else:
                out = img.filter(ImageFilter.GaussianBlur(radius))
            out.save(os.path.join(output_dir, fname))
            count += 1
    return count

