from PIL import Image

def _bucket_for(max_dim):
    if max_dim < 640:
        return 'small'
    if max_dim <= 1920:
        return 'medium'
    return 'large'

def organize_by_resolution(input_dir, output_dir):
    valid_ext = ('.png', '.jpg', '.jpeg')
    counts = {'small': 0, 'medium': 0, 'large': 0}
    for bucket in counts:
        os.makedirs(os.path.join(output_dir, bucket), exist_ok=True)
    for fname in sorted(os.listdir(input_dir)):
        if not fname.lower().endswith(valid_ext):
            continue
        path = os.path.join(input_dir, fname)
        try:
            with Image.open(path) as img:
                bucket = _bucket_for(max(img.width, img.height))
            shutil.copy2(path, os.path.join(output_dir, bucket, fname))
            counts[bucket] += 1
        except Exception:
            continue
    return counts

import os
from PIL import Image

def bulk_reencode(input_dir, output_dir, quality):
    if not (1 <= quality <= 95):
        raise ValueError('quality must be between 1 and 95')
    os.makedirs(output_dir, exist_ok=True)
    valid_ext = ('.png', '.jpg', '.jpeg')
    report = {}
    for fname in sorted(os.listdir(input_dir)):
        if not fname.lower().endswith(valid_ext):
            continue
        src_path = os.path.join(input_dir, fname)
        stem = os.path.splitext(fname)[0]
        out_path = os.path.join(output_dir, stem + '.jpg')
        original_bytes = os.path.getsize(src_path)
        with Image.open(src_path) as img:
            if img.mode != 'RGB':
                img = img.convert('RGB')
            img.save(out_path, format='JPEG', quality=quality)
        reencoded_bytes = os.path.getsize(out_path)
        ratio = round(original_bytes / reencoded_bytes, 3) if reencoded_bytes else 0.0
        report[fname] = {'original_bytes': original_bytes, 'reencoded_bytes': reencoded_bytes, 'ratio': ratio}
    return report

