import os
from PIL import Image

def _normalized_hist(path):
    with Image.open(path) as img:
        hist = img.convert('L').histogram()
    total = sum(hist)
    return [c / total for c in hist]

def _l1_distance(h1, h2):
    return sum(abs(a - b) for a, b in zip(h1, h2))

def find_near_duplicates(input_dir, threshold):
    if not (0 <= threshold <= 2):
        raise ValueError('threshold must be within [0, 2]')
    valid_ext = ('.png', '.jpg', '.jpeg')
    filenames = sorted(f for f in os.listdir(input_dir) if f.lower().endswith(valid_ext))
    hists = {f: _normalized_hist(os.path.join(input_dir, f)) for f in filenames}
    parent = {f: f for f in filenames}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    for i in range(len(filenames)):
        for j in range(i + 1, len(filenames)):
            a, b = filenames[i], filenames[j]
            if _l1_distance(hists[a], hists[b]) <= threshold:
                union(a, b)

    groups = {}
    for f in filenames:
        groups.setdefault(find(f), []).append(f)
    clusters = [sorted(v) for v in groups.values() if len(v) >= 2]
    return sorted(clusters, key=lambda c: c[0])

