def find_fuzzy_duplicates(input_dir, hash_size=8, max_hamming=5):
    total_bits = hash_size * hash_size
    if not (0 <= max_hamming <= total_bits):
        raise ValueError('max_hamming out of valid range')
    valid_ext = ('.png', '.jpg', '.jpeg')
    filenames = sorted(f for f in os.listdir(input_dir) if f.lower().endswith(valid_ext))
    hashes = {f: _ahash(os.path.join(input_dir, f), hash_size) for f in filenames}
    parent = {f: f for f in filenames}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    for i in range(len(filenames)):
        for j in range(i + 1, len(filenames)):
            a, b = filenames[i], filenames[j]
            dist = bin(hashes[a] ^ hashes[b]).count('1')
            if dist <= max_hamming:
                union(a, b)

    groups = {}
    for f in filenames:
        groups.setdefault(find(f), []).append(f)
    clusters = [sorted(v) for v in groups.values() if len(v) >= 2]
    return sorted(clusters, key=lambda c: c[0])

import os
from PIL import Image

def _channel_mean(band):
    hist = band.histogram()
    total = sum(hist)
    return sum(i * c for i, c in enumerate(hist)) / total

def _classify(brightness):
    if brightness < 85:
        return 'dark'
    if brightness <= 170:
        return 'normal'
    return 'bright'

def analyze_brightness(input_dir):
    valid_ext = ('.png', '.jpg', '.jpeg')
    results = {}
    for fname in sorted(os.listdir(input_dir)):
        if not fname.lower().endswith(valid_ext):
            continue
        path = os.path.join(input_dir, fname)
        try:
            with Image.open(path) as img:
                rgb = img.convert('RGB')
                r, g, b = rgb.split()
                gray = rgb.convert('L')
                brightness = _channel_mean(gray)
                results[fname] = {
                    'r_mean': round(_channel_mean(r), 2),
                    'g_mean': round(_channel_mean(g), 2),
                    'b_mean': round(_channel_mean(b), 2),
                    'brightness': round(brightness, 2),
                    'classification': _classify(brightness)
                }
        except Exception:
            continue
    return results

import os
from PIL import Image

VALID_POSITIONS = ('top-left', 'top-right', 'bottom-left', 'bottom-right', 'center')

def _compute_position(base_size, wm_size, position, margin):
    bw, bh = base_size
    ww, wh = wm_size
    if position == 'top-left':
        return (margin, margin)
    if position == 'top-right':
        return (bw - ww - margin, margin)
    if position == 'bottom-left':
        return (margin, bh - wh - margin)
    if position == 'bottom-right':
        return (bw - ww - margin, bh - wh - margin)
    return ((bw - ww) // 2, (bh - wh) // 2)

def apply_watermark(input_dir, output_dir, watermark_path, opacity, position='bottom-right', margin=10):
    if not (0.0 <= opacity <= 1.0):
        raise ValueError('opacity must be within [0.0, 1.0]')
    if position not in VALID_POSITIONS:
        raise ValueError('invalid position')
    os.makedirs(output_dir, exist_ok=True)
    valid_ext = ('.png', '.jpg', '.jpeg')
    with Image.open(watermark_path) as wm_src:
        watermark_master = wm_src.convert('RGBA')
    count = 0
    for fname in sorted(os.listdir(input_dir)):
        if not fname.lower().endswith(valid_ext):
            continue
        with Image.open(os.path.join(input_dir, fname)) as base:
            base = base.convert('RGBA')
            wm = watermark_master.copy()
            if wm.width > base.width or wm.height > base.height:
                scale = min(base.width / wm.width, base.height / wm.height)
                wm = wm.resize((max(1, int(wm.width * scale)), max(1, int(wm.height * scale))), Image.LANCZOS)
            alpha = wm.split()[-1].point(lambda a: int(a * opacity))
            pos = _compute_position(base.size, wm.size, position, margin)
            base.paste(wm, pos, mask=alpha)
            base.convert('RGB').save(os.path.join(output_dir, fname))
            count += 1
    return count

