def build_dedup_archive(input_dir, archive_dir):
    os.makedirs(archive_dir, exist_ok=True)
    rel_paths = []
    for root, _, files in os.walk(input_dir):
        for fname in files:
            full = os.path.join(root, fname)
            rel_paths.append(os.path.relpath(full, input_dir))
    rel_paths.sort()
    seen = {}
    total_scanned = 0
    duplicate_count = 0
    for rel in rel_paths:
        full = os.path.join(input_dir, rel)
        digest = _file_hash(full)
        total_scanned += 1
        if digest in seen:
            duplicate_count += 1
            continue
        seen[digest] = rel
        ext = os.path.splitext(rel)[1].lower()
        shutil.copy2(full, os.path.join(archive_dir, digest[:16] + ext))
    return {'unique_count': len(seen), 'duplicate_count': duplicate_count, 'total_scanned': total_scanned}

import os
from PIL import Image, ImageFilter

def denoise_median(input_dir, output_dir, kernel_size):
    if kernel_size < 3 or kernel_size % 2 == 0:
        raise ValueError('kernel_size must be an odd integer >= 3')
    os.makedirs(output_dir, exist_ok=True)
    valid_ext = ('.png', '.jpg', '.jpeg')
    results = {}
    for fname in sorted(os.listdir(input_dir)):
        if not fname.lower().endswith(valid_ext):
            continue
        path = os.path.join(input_dir, fname)
        try:
            with Image.open(path) as img:
                filtered = img.filter(ImageFilter.MedianFilter(size=kernel_size))
                filtered.save(os.path.join(output_dir, fname))
                results[fname] = {'width': filtered.width, 'height': filtered.height}
        except Exception:
            continue
    return results

import os
from PIL import Image

def extract_patches(image_path, patch_size, stride, output_dir):
    pw, ph = patch_size
    sx, sy = stride
    os.makedirs(output_dir, exist_ok=True)
    with Image.open(image_path) as img:
        iw, ih = img.size
        num_cols = (iw - pw) // sx + 1 if iw >= pw else 0
        num_rows = (ih - ph) // sy + 1 if ih >= ph else 0
        if num_rows == 0 or num_cols == 0:
            return (num_rows, num_cols)
        for row in range(num_rows):
            for col in range(num_cols):
                left = col * sx
                top = row * sy
                box = (left, top, left + pw, top + ph)
                patch = img.crop(box)
                patch.save(os.path.join(output_dir, f'{row}_{col}.png'))
    return (num_rows, num_cols)
